                self.responses.id(),
                self.collected_operations.id(),
                self.collected_operations_per_thread.id(),
            ),
    {
        atomic_with_ghost!(
            &self.combiner.0 => store(0);
            update old_val -> new_val;
            ghost g
            => {
                g = Option::Some(lock_state.get());
            });
    }

